if isclass(condition) and issubclass(condition, BaseException):
    exc_types = (condition,)
elif isinstance(condition, tuple):
    if not condition:
        raise ValueError("condition tuple must not be empty")

    for cls in condition:
        if not (isclass(cls) and issubclass(cls, BaseException)):
            raise TypeError(
                "condition tuple must contain only exception types"
            )

    exc_types = condition
elif callable(condition):
    # If condition is a callable (but not an exception class), return it
    # directly
    return cast(Callable[[_BaseExceptionT_co], bool], condition)
else:
    raise TypeError(
        "expected a function, exception type or tuple of exception types"
    )

# For exception type(s), create a function that checks isinstance
return lambda exc: check_direct_subclass(exc, exc_types)

